CREATE TABLE IF NOT EXISTS `email_marketing_settings` (`setting_name` varchar(100) NOT NULL,`setting_value` text NOT NULL,PRIMARY KEY (`setting_name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `email_marketing_settings` (`setting_name`,`setting_value`) VALUES ('enabled','0'),('default_sender_name','Esteem Energy'),('default_reply_to',''),('batch_size','25'),('delay_between_messages','0'),('company_footer','Esteem Energy<br>Australia'),('test_mode','1'),('approved_test_emails','') ON DUPLICATE KEY UPDATE setting_name=VALUES(setting_name);
CREATE TABLE IF NOT EXISTS `email_campaigns` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(190) NOT NULL,`subject` varchar(255) NOT NULL,`preview_text` varchar(255) DEFAULT '',`html_content` mediumtext NOT NULL,`sender_name` varchar(190) NOT NULL,`reply_to` varchar(190) DEFAULT '',`send_at` datetime DEFAULT NULL,`test_recipient` varchar(190) DEFAULT '',`segment_filters` text DEFAULT NULL,`last_eligible_count` int NOT NULL DEFAULT 0,`status` enum('draft','scheduled','sending','paused','completed','failed') NOT NULL DEFAULT 'draft',`created_by` int NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime DEFAULT NULL,PRIMARY KEY (`id`),KEY `campaign_status_send_at` (`status`,`send_at`),KEY `campaign_created_by` (`created_by`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE `email_campaigns` ADD COLUMN IF NOT EXISTS `test_contact_id` int NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS `test_contact_type` varchar(20) NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS `email_templates` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(190) NOT NULL,`subject` varchar(255) NOT NULL,`html_content` mediumtext NOT NULL,`created_by` int NOT NULL,`created_at` datetime NOT NULL,PRIMARY KEY (`id`),KEY `template_name` (`name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `marketing_consent` (`id` int NOT NULL AUTO_INCREMENT,`entity_type` enum('lead','client') NOT NULL,`entity_id` int NOT NULL,`email` varchar(190) NOT NULL,`consent` enum('Unknown','Opted In','Opted Out') NOT NULL DEFAULT 'Unknown',`updated_at` datetime NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `entity_consent` (`entity_type`,`entity_id`),KEY `email_consent` (`email`,`consent`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `email_suppressions` (`id` int NOT NULL AUTO_INCREMENT,`email` varchar(190) NOT NULL,`entity_type` varchar(20) DEFAULT '',`entity_id` int DEFAULT 0,`reason` varchar(100) NOT NULL DEFAULT 'unsubscribe',`created_at` datetime NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `suppressed_email` (`email`),KEY `suppression_entity` (`entity_type`,`entity_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `email_campaign_recipients` (`id` bigint NOT NULL AUTO_INCREMENT,`campaign_id` int NOT NULL,`entity_type` varchar(20) NOT NULL,`entity_id` int NOT NULL,`email` varchar(190) NOT NULL,`recipient_name` varchar(190) DEFAULT '',`status` enum('queued','sent','failed','bounced','skipped','unsubscribed') NOT NULL DEFAULT 'queued',`is_test` tinyint(1) NOT NULL DEFAULT 0,`queued_at` datetime NOT NULL,`sent_at` datetime DEFAULT NULL,`error_details` varchar(500) DEFAULT NULL,PRIMARY KEY (`id`),UNIQUE KEY `campaign_recipient` (`campaign_id`,`email`),KEY `queue_status` (`status`,`queued_at`),KEY `recipient_email` (`email`),KEY `recipient_test_status` (`is_test`,`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE `email_campaign_recipients` ADD COLUMN IF NOT EXISTS `is_test` tinyint(1) NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS `email_automation_rules` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(190) NOT NULL,`trigger_type` enum('new_lead','quote_sent','no_response') NOT NULL,`delay_minutes` int NOT NULL DEFAULT 0,`no_response_days` int NOT NULL DEFAULT 3,`status_ids` varchar(255) NOT NULL DEFAULT '',`quote_status_id` int NOT NULL DEFAULT 0,`template_id` int NOT NULL DEFAULT 0,`enabled` tinyint(1) NOT NULL DEFAULT 0,`created_by` int NOT NULL,`created_at` datetime NOT NULL,PRIMARY KEY (`id`),KEY `automation_enabled_trigger` (`enabled`,`trigger_type`),KEY `automation_quote_status` (`trigger_type`,`quote_status_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `email_marketing_settings` (`setting_name`,`setting_value`) VALUES ('last_no_response_run_date','') ON DUPLICATE KEY UPDATE setting_name=VALUES(setting_name);
CREATE TABLE IF NOT EXISTS `email_automation_queue` (`id` bigint NOT NULL AUTO_INCREMENT,`rule_id` int NOT NULL,`entity_type` varchar(20) NOT NULL,`entity_id` int NOT NULL,`email` varchar(190) NOT NULL,`available_at` datetime NOT NULL,`status` enum('queued','sent','failed','skipped') NOT NULL DEFAULT 'queued',`created_at` datetime NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `automation_dedupe` (`rule_id`,`entity_type`,`entity_id`),KEY `automation_queue` (`status`,`available_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `email_automation_audit` (`id` bigint NOT NULL AUTO_INCREMENT,`rule_id` int NOT NULL,`entity_type` varchar(20) NOT NULL,`entity_id` int NOT NULL,`template_id` int NOT NULL DEFAULT 0,`campaign_id` int NOT NULL DEFAULT 0,`queue_id` bigint NOT NULL DEFAULT 0,`trigger_type` varchar(40) NOT NULL,`created_at` datetime NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `automation_event_once` (`rule_id`,`entity_type`,`entity_id`,`trigger_type`),KEY `automation_audit_time` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `email_campaign_status_history` (`id` bigint NOT NULL AUTO_INCREMENT,`campaign_id` int NOT NULL,`from_status` varchar(20) DEFAULT '',`to_status` varchar(20) NOT NULL,`changed_by` int NOT NULL DEFAULT 0,`changed_at` datetime NOT NULL,PRIMARY KEY (`id`),KEY `campaign_history_campaign` (`campaign_id`,`changed_at`),KEY `campaign_history_status` (`to_status`,`changed_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `email_test_send_log` (`id` bigint NOT NULL AUTO_INCREMENT,`campaign_id` int NOT NULL DEFAULT 0,`contact_id` int NOT NULL DEFAULT 0,`email` varchar(190) NOT NULL DEFAULT '',`status` enum('queued','sent','blocked','failed') NOT NULL,`error_details` varchar(500) DEFAULT NULL,`created_at` datetime NOT NULL,PRIMARY KEY (`id`),KEY `test_send_campaign` (`campaign_id`,`created_at`),KEY `test_send_status` (`status`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
